INSERT OR IGNORE INTO facts (candidate,text,source,url,category,sort) VALUES ('Robert White','From 2008 to 2013, he was legislative counsel in the office of Eleanor Holmes Norton, the District of Columbia''s Delegate to the United States House of Representatives.','Wikipedia','https://en.wikipedia.org/wiki/Robert_White_(Washington,_D.C._politician)','bio',101);
INSERT OR IGNORE INTO facts (candidate,text,source,url,category,sort) VALUES ('Robert White','In 2014, he was an unsuccessful candidate for an at-large seat on the council, placing fourth out of 16.','Wikipedia','https://en.wikipedia.org/wiki/Robert_White_(Washington,_D.C._politician)','bio',102);
INSERT OR IGNORE INTO facts (candidate,text,source,url,category,sort) VALUES ('Robert White','He won the Democratic primary for the at-large seat in 2016, defeating 12-year incumbent Vincent Orange.','Wikipedia','https://en.wikipedia.org/wiki/Robert_White_(Washington,_D.C._politician)','bio',103);
INSERT OR IGNORE INTO facts (candidate,text,source,url,category,sort) VALUES ('Robert White','After Orange resigned his seat, White was appointed to Orange''s complete term, and sworn in on September 16, 2016.','Wikipedia','https://en.wikipedia.org/wiki/Robert_White_(Washington,_D.C._politician)','bio',104);
INSERT OR IGNORE INTO facts (candidate,text,source,url,category,sort) VALUES ('Robert White','He won election to his seat in November 2016 with 217,834 votes, which counted for 38% of the total votes.','Wikipedia','https://en.wikipedia.org/wiki/Robert_White_(Washington,_D.C._politician)','bio',105);
INSERT OR IGNORE INTO facts (candidate,text,source,url,category,sort) VALUES ('Robert White','In October 2021, he announced his candidacy for mayor in the 2022 election.','Wikipedia','https://en.wikipedia.org/wiki/Robert_White_(Washington,_D.C._politician)','bio',106);
INSERT OR IGNORE INTO facts (candidate,text,source,url,category,sort) VALUES ('Robert White','In June 2022, he finished second in the Democratic Primary, losing to incumbent Bowser.','Wikipedia','https://en.wikipedia.org/wiki/Robert_White_(Washington,_D.C._politician)','bio',107);
INSERT OR IGNORE INTO facts (candidate,text,source,url,category,sort) VALUES ('Robert White','White is the Democratic nominee in the 2026 election to be the District of Columbia''s congressional delegate, the position Eleanor Holmes Norton holds.','Wikipedia','https://en.wikipedia.org/wiki/Robert_White_(Washington,_D.C._politician)','bio',108);
INSERT OR IGNORE INTO facts (candidate,text,source,url,category,sort) VALUES ('Robert White','Robert White was born in Washington, D.C., in 1982 to Robert "Bobby" White Sr. and his wife, Tamara (née Richards).','Wikipedia','https://en.wikipedia.org/wiki/Robert_White_(Washington,_D.C._politician)','bio',109);
INSERT OR IGNORE INTO facts (candidate,text,source,url,category,sort) VALUES ('Robert White','His father is a fourth-generation Washingtonian, and a deacon in the Catholic Church.','Wikipedia','https://en.wikipedia.org/wiki/Robert_White_(Washington,_D.C._politician)','bio',110);
INSERT OR IGNORE INTO facts (candidate,text,source,url,category,sort) VALUES ('Robert White','His parents divorced when he was young, and his mother died from breast cancer in September 1990 when he was eight years old.','Wikipedia','https://en.wikipedia.org/wiki/Robert_White_(Washington,_D.C._politician)','bio',111);
INSERT OR IGNORE INTO facts (candidate,text,source,url,category,sort) VALUES ('Robert White','A month after her death, he was critically injured when a semi-trailer truck side-swiped a passenger vehicle in which he was riding on New Hampshire Avenue in Montgomery County, Maryland.','Wikipedia','https://en.wikipedia.org/wiki/Robert_White_(Washington,_D.C._politician)','bio',112);
INSERT OR IGNORE INTO facts (candidate,text,source,url,category,sort) VALUES ('Robert White','The automobile spun, flipped over, struck the median, flipped into the air, and landed on the hood of another car in the opposite lane.','Wikipedia','https://en.wikipedia.org/wiki/Robert_White_(Washington,_D.C._politician)','bio',113);
INSERT OR IGNORE INTO facts (candidate,text,source,url,category,sort) VALUES ('Robert White','He suffered a severe skull fracture, and underwent several operations before making a full recovery.','Wikipedia','https://en.wikipedia.org/wiki/Robert_White_(Washington,_D.C._politician)','bio',114);
INSERT OR IGNORE INTO facts (candidate,text,source,url,category,sort) VALUES ('Robert White','White attended the private Archbishop Carroll High School in Washington, D.C., where he began playing lacrosse his senior year.','Wikipedia','https://en.wikipedia.org/wiki/Robert_White_(Washington,_D.C._politician)','bio',115);
INSERT OR IGNORE INTO facts (candidate,text,source,url,category,sort) VALUES ('Robert White','He graduated in 2004 with a bachelor''s degree in political science and philosophy.','Wikipedia','https://en.wikipedia.org/wiki/Robert_White_(Washington,_D.C._politician)','bio',116);
INSERT OR IGNORE INTO facts (candidate,text,source,url,category,sort) VALUES ('Robert White','He is the first member of his family to graduate from college.','Wikipedia','https://en.wikipedia.org/wiki/Robert_White_(Washington,_D.C._politician)','bio',117);
INSERT OR IGNORE INTO facts (candidate,text,source,url,category,sort) VALUES ('Robert White','White enrolled in law school at American University Washington College of Law in Washington, D.C. where he served on the Administrative Law Review and graduated with a Juris Doctor in 2007.','Wikipedia','https://en.wikipedia.org/wiki/Robert_White_(Washington,_D.C._politician)','bio',118);
INSERT OR IGNORE INTO facts (candidate,text,source,url,category,sort) VALUES ('Robert White','From 2007 to 2008, White was a law clerk for the Maryland District Court for Montgomery County, Maryland, and at the law firm of Webster, Fredrickson, Correia & Puth.','Wikipedia','https://en.wikipedia.org/wiki/Robert_White_(Washington,_D.C._politician)','bio',119);
INSERT OR IGNORE INTO facts (candidate,text,source,url,category,sort) VALUES ('Robert White','In July 2008, White took a position as legislative counsel to Delegate Eleanor Holmes Norton.','Wikipedia','https://en.wikipedia.org/wiki/Robert_White_(Washington,_D.C._politician)','bio',120);
