INSERT OR IGNORE INTO facts (candidate,text,source,url,category,sort) VALUES ('Robert White','In January 2013, White was a co-founder of the Brightwood Park Citizens Association, and was elected its founding president.','Wikipedia','https://en.wikipedia.org/wiki/Robert_White_(Washington,_D.C._politician)','bio',122);
