INSERT OR IGNORE INTO facts (candidate,text,source,url,category,sort) VALUES ('Robert White','The editorial board of The Washington Post endorsed Orange''s candidacy, praising him for his legislative skills and focus on economic development.','Wikipedia','https://en.wikipedia.org/wiki/Robert_White_(Washington,_D.C._politician)','bio',144);
INSERT OR IGNORE INTO facts (candidate,text,source,url,category,sort) VALUES ('Robert White','White also won endorsements from several tenants'' rights groups, an LGBT activists'' group, a Latino political group, several other progressive political organizations, and Ward 8 city council candidate Trayon White.','Wikipedia','https://en.wikipedia.org/wiki/Robert_White_(Washington,_D.C._politician)','bio',145);
