INSERT OR IGNORE INTO facts (candidate,text,source,url,category,sort) VALUES ('Robert White','During the last three months of the primary campaign, White raised more than $96,000, surpassing the $61,000 raised by Vincent Orange.','Wikipedia','https://en.wikipedia.org/wiki/Robert_White_(Washington,_D.C._politician)','bio',147);
