INSERT OR IGNORE INTO facts (candidate,text,source,url,category,sort) VALUES ('Robert White','He also attacked Orange''s ideas for economic development as kooky and ineffective, and called his tenure as the council''s workforce development overseer lackluster.','Wikipedia','https://en.wikipedia.org/wiki/Robert_White_(Washington,_D.C._politician)','bio',151);
INSERT OR IGNORE INTO facts (candidate,text,source,url,category,sort) VALUES ('Robert White','White also criticized David Garber, widely considered Orange''s top challenger, for ignoring African American and poor neighborhoods.','Wikipedia','https://en.wikipedia.org/wiki/Robert_White_(Washington,_D.C._politician)','bio',152);
INSERT OR IGNORE INTO facts (candidate,text,source,url,category,sort) VALUES ('Robert White','On June 14, 2016, Robert White defeated Vincent Orange and David Garber to win the Democratic Party nomination for the at-large seat on the city council.','Wikipedia','https://en.wikipedia.org/wiki/Robert_White_(Washington,_D.C._politician)','bio',153);
INSERT OR IGNORE INTO facts (candidate,text,source,url,category,sort) VALUES ('Robert White','The Washington Post said unnamed political observers attributed White''s win to White''s persistent attacks on Orange''s ethics, his use of a paid staff, and an anti-incumbent feeling among voters.','Wikipedia','https://en.wikipedia.org/wiki/Robert_White_(Washington,_D.C._politician)','bio',154);
