INSERT OR IGNORE INTO facts (candidate,text,source,url,category,sort) VALUES ('Robert White','On November 8, 2016, White easily won election to the seat to which he had been temporarily appointed.','Wikipedia','https://en.wikipedia.org/wiki/Robert_White_(Washington,_D.C._politician)','bio',161);
